query HydrateShop($shopifyId: ID!) {
  shopByShopifyId(shopifyId: $shopifyId) {
    id
    uuid
    name
    defaultHandle
    followedByMe
    shopNetwork
    shareUrl
    recognizedWebsiteUrl: websiteUrl(includeRecognition: true)
    websiteUrl
    shopifyId
    nativeProductPagesEnabled
    inAppVisibilityStatus
    storeEligible
    productReviewAnalytics {
      totalProductReviews
      totalProductRatings
      averageRating
      __typename
    }
    shopCashIncentive {
      ...ShopCashIncentiveFragment
      __typename
    }
    visualTheme {
      id
      logoImage {
        ...ReducedImage
        __typename
      }
      featuredImages {
        ...ReducedImage
        __typename
      }
      description
      brandSettings {
        ...BrandSettings
        __typename
      }
      __typename
    }
    offers {
      ... on AutomaticDiscount {
        id
        __typename
      }
      __typename
    }
    __typename
  }
}

